1: /**
2:  * server/resolver.js - Stream Resolver Engine for cinejoy-webos
3:  * 
4:  * Executes WebAssembly crush.wasm request sealing, binary POST to api.wing.st/g,
5:  * AES-256-GCM response decryption, and multi-server fallback resolution.
6:  */
7: 
8: const crypto = require('crypto');
9: const fs = require('fs');
10: const path = require('path');
11: 
12: // Protocol Constants
13: const PROTOCOL_ID = 'lumen-gate-v2';
14: const RANDOM_SEED_LEN = 44;
15: const AES_KEY_LEN = 32;
16: const KEY_ID_LEN = 1;
17: const EC_PUBKEY_LEN = 65;
18: const HEADER_LEN = 98; // 32 + 1 + 65
19: const GCM_IV_LEN = 12;
20: const GCM_TAG_LEN = 16;
21: const OUT_BUF_MAX = 4096;
22: 
23: const GATEWAY_URL = 'https://api.wing.st/g';
24: const SERVERS_URL = 'https://api.wing.st/servers';
25: const WASM_REMOTE_URL = 'https://api.wing.st/crush.wasm';
26: const SUBS_URL = 'https://subs.wing.st/subtitles';
27: 
28: const SERVERS_CACHE_TTL_MS = 300_000; // 5 minutes
29: 
30: // State Caches
31: let cachedWasmModule = null;
32: let cachedServersData = null;
33: let lastServersFetchTime = 0;
34: 
35: /**
36:  * Loads and compiles the crush.wasm WebAssembly module.
37:  * Prioritizes local disk file, falls back to remote download.
38:  * 
39:  * @param {string} [customPath] - Optional custom path to crush.wasm
40:  * @returns {Promise<WebAssembly.Module>} Compiled WebAssembly module
41:  */
42: async function initWasm(customPath) {
43:   if (cachedWasmModule) {
44:     return cachedWasmModule;
45:   }
46: 
47:   const defaultPath = path.resolve(__dirname, 'crush.wasm');
48:   const wasmPath = customPath || defaultPath;
49: 
50:   let wasmBuffer;
51:   if (fs.existsSync(wasmPath)) {
52:     wasmBuffer = fs.readFileSync(wasmPath);
53:   } else {
54:     // Fallback: fetch from remote endpoint
55:     const res = await fetch(WASM_REMOTE_URL);
56:     if (!res.ok) {
57:       throw new Error(`Failed to download crush.wasm: HTTP ${res.status} ${res.statusText}`);
58:     }
59:     const arrayBuf = await res.arrayBuffer();
60:     wasmBuffer = Buffer.from(arrayBuf);
61:     try {
62:       fs.writeFileSync(wasmPath, wasmBuffer);
63:     } catch {
64:       // Ignore write errors in read-only filesystems
65:     }
66:   }
67: 
68:   cachedWasmModule = await WebAssembly.compile(wasmBuffer);
69:   return cachedWasmModule;
70: }
71: 
72: /**
73:  * Retrieves the active streaming server cluster list.
74:  * 
75:  * @param {boolean} [forceRefresh=false] - Force bypass cache
76:  * @returns {Promise<{ servers: Array<object> }>} Cluster servers response object
77:  */
78: async function getServers(forceRefresh = false) {
79:   const now = Date.now();
80:   if (!forceRefresh && cachedServersData && (now - lastServersFetchTime < SERVERS_CACHE_TTL_MS)) {
81:     return cachedServersData;
82:   }
83: 
84:   try {
85:     const res = await fetch(SERVERS_URL, {
86:       signal: AbortSignal.timeout(5000)
87:     });
88:     if (!res.ok) {
89:       throw new Error(`HTTP ${res.status}`);
90:     }
91:     const data = await res.json();
92:     cachedServersData = {
93:       servers: Array.isArray(data.servers) ? data.servers : []
94:     };
95:     lastServersFetchTime = now;
96:     return cachedServersData;
97:   } catch (err) {
98:     if (cachedServersData) {
99:       return cachedServersData; // Use stale cache on error
100:     }
101:     // Hardcoded fallback if endpoint is unreachable
102:     cachedServersData = {
103:       servers: [
104:         { name: 'secret', status: 'ok', '4k': true },
105:         { name: 'Nebula', status: 'ok', '4k': false },
106:         { name: 'Lisbon', status: 'ok', '4k': true },
107:         { name: 'Solara', status: 'ok', '4k': false },
108:         { name: 'Athens', status: 'ok', '4k': false }
109:       ]
110:     };
111:     return cachedServersData;
112:   }
113: }
114: 
115: /**
116:  * Executes request sealing in crush.wasm.
117:  * 
118:  * @param {WebAssembly.Instance} wasmInstance
119:  * @param {object} params
120:  * @param {string} params.server
121:  * @param {string} params.type - 'movie' | 'tv' | 'series'
122:  * @param {string|number} params.tmdbId
123:  * @param {string|number} [params.season]
124:  * @param {string|number} [params.episode]
125:  * @returns {{ responseKey: Buffer, keyId: number, ephemeralPublic: Buffer, ciphertextBody: Buffer }}
126:  */
127: function sealRequest(wasmInstance, { server, type, tmdbId, season, episode }) {
128:   const exports = wasmInstance.exports;
129:   const wasmType = (type === 'tv' || type === 'series') ? 'series' : 'movie';
130:   
131:   const payloadObj = { tmdb: String(tmdbId) };
132:   if (wasmType === 'series') {
133:     payloadObj.season = String(season || 1);
134:     payloadObj.episode = String(episode || 1);
135:   }
136: 
137:   const payloadJson = JSON.stringify({
138:     path: `/${server}/${wasmType}`,
139:     payload: payloadObj
140:   });
141: 
142:   const encodedPayload = Buffer.from(payloadJson, 'utf8');
143:   const randBytes = crypto.randomBytes(RANDOM_SEED_LEN);
144: 
145:   const payloadPtr = exports.alloc(encodedPayload.length);
146:   const randPtr = exports.alloc(randBytes.length);
147:   const outPtr = exports.alloc(OUT_BUF_MAX);
148: 
149:   const mem = new Uint8Array(exports.memory.buffer);
150:   mem.set(encodedPayload, payloadPtr);
151:   mem.set(randBytes, randPtr);
152: 
153:   const sealedLen = exports.seal_request(
154:     payloadPtr, encodedPayload.length,
155:     randPtr, randBytes.length,
156:     outPtr, OUT_BUF_MAX
157:   );
158: 
159:   if (sealedLen <= HEADER_LEN) {
160:     exports.dealloc(payloadPtr, encodedPayload.length);
161:     exports.dealloc(randPtr, randBytes.length);
162:     exports.dealloc(outPtr, OUT_BUF_MAX);
163:     throw new Error(`WASM seal_request returned invalid length: ${sealedLen}`);
164:   }
165: 
166:   const sealedBuffer = Buffer.from(exports.memory.buffer, outPtr, sealedLen);
167:   const responseKey = Buffer.from(sealedBuffer.subarray(0, AES_KEY_LEN));
168:   const keyId = sealedBuffer[AES_KEY_LEN];
169:   const ephemeralPublic = Buffer.from(sealedBuffer.subarray(AES_KEY_LEN + KEY_ID_LEN, HEADER_LEN));
170:   const ciphertextBody = Buffer.from(sealedBuffer.subarray(HEADER_LEN, sealedLen));
171: 
172:   // Free allocated linear memory
173:   exports.dealloc(payloadPtr, encodedPayload.length);
174:   exports.dealloc(randPtr, randBytes.length);
175:   exports.dealloc(outPtr, OUT_BUF_MAX);
176: 
177:   return { responseKey, keyId, ephemeralPublic, ciphertextBody };
178: }
179: 
180: /**
181:  * Decrypts AES-256-GCM gateway response using Node.js crypto.
182:  * 
183:  * @param {Buffer} respBuf - Raw response from api.wing.st/g
184:  * @param {Buffer} responseKey - 32-byte AES key
185:  * @param {number} keyId - Key version byte
186:  * @param {Buffer} ephemeralPublic - 65-byte public key
187:  * @returns {object} Decoded JSON response
188:  */
189: function decryptResponse(respBuf, responseKey, keyId, ephemeralPublic) {
190:   if (respBuf.length < GCM_IV_LEN + GCM_TAG_LEN) {
191:     throw new Error(`Gateway response buffer too short: ${respBuf.length} bytes (minimum 28 required)`);
192:   }
193: 
194:   const iv = respBuf.subarray(0, GCM_IV_LEN);
195:   const authTag = respBuf.subarray(respBuf.length - GCM_TAG_LEN);
196:   const ciphertext = respBuf.subarray(GCM_IV_LEN, respBuf.length - GCM_TAG_LEN);
197: 
198:   const aad = Buffer.concat([
199:     Buffer.from(PROTOCOL_ID, 'utf8'),
200:     Buffer.from([0, 2, keyId]),
201:     ephemeralPublic
202:   ]);
203: 
204:   const decipher = crypto.createDecipheriv('aes-256-gcm', responseKey, iv);
205:   decipher.setAAD(aad);
206:   decipher.setAuthTag(authTag);
207: 
208:   const decrypted = Buffer.concat([
209:     decipher.update(ciphertext),
210:     decipher.final()
211:   ]);
212: 
213:   return JSON.parse(decrypted.toString('utf8'));
214: }
215: 
216: /**
217:  * Attempts stream resolution on a single named server node.
218:  * 
219:  * @private
220:  */
221: async function resolveSingleServer({ server, type, tmdbId, season, episode, wasmModule }) {
222:   const instance = await WebAssembly.instantiate(wasmModule);
223:   const { responseKey, keyId, ephemeralPublic, ciphertextBody } = sealRequest(instance, {
224:     server, type, tmdbId, season, episode
225:   });
226: 
227:   const gatewayRes = await fetch(GATEWAY_URL, {
228:     method: 'POST',
229:     headers: {
230:       'Content-Type': 'text/plain;charset=UTF-8',
231:       'Origin': 'https://cinejoy.pk',
232:       'Referer': 'https://cinejoy.pk/',
233:       'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36'
234:     },
235:     body: ciphertextBody,
236:     signal: AbortSignal.timeout(10000)
237:   });
238: 
239:   if (!gatewayRes.ok) {
240:     throw new Error(`Gateway returned HTTP ${gatewayRes.status} ${gatewayRes.statusText}`);
241:   }
242: 
243:   const respBuf = Buffer.from(await gatewayRes.arrayBuffer());
244:   const decrypted = decryptResponse(respBuf, responseKey, keyId, ephemeralPublic);
245: 
246:   if (decrypted.status !== 200) {
247:     const errorMsg = decrypted.data?.error || `Status ${decrypted.status}`;
248:     throw new Error(`${server}: ${errorMsg}`);
249:   }
250: 
251:   const stream = decrypted.data?.stream?.[0];
252:   if (!stream || !stream.playlist) {
253:     throw new Error(`${server}: No playable playlist returned`);
254:   }
255: 
256:   return {
257:     playlist: stream.playlist,
258:     captions: stream.captions || [],
259:     server,
260:     rawStream: stream
261:   };
262: }
263: 
264: /**
265:  * Main export: Resolves stream with multi-server fallback.
266:  * 
267:  * @param {object} options
268:  * @param {string|number} options.tmdbId - TMDB movie/show ID
269:  * @param {string} [options.type='movie'] - 'movie' or 'tv'
270:  * @param {string|number} [options.season] - Season number for TV
271:  * @param {string|number} [options.episode] - Episode number for TV
272:  * @param {string} [options.server='secret'] - Preferred server name or 'auto'
273:  * @param {boolean} [options.fallback=true] - Enable multi-server fallback
274:  * @returns {Promise<{ success: boolean, playlist: string, originalUrl: string, streamUrl: string, server: string, format: string, captions: Array, rawStream: object }>}
275:  */
276: async function resolveStream({ tmdbId, type = 'movie', season, episode, server = 'secret', fallback = true }) {
277:   if (!tmdbId) {
278:     throw new Error('tmdbId is required for stream resolution');
279:   }
280: 
281:   const wasmModule = await initWasm();
282:   const clusterData = await getServers();
283:   const serverList = Array.isArray(clusterData.servers) ? clusterData.servers : [];
284:   const serverNames = serverList.map(s => s.name);
285: 
286:   // If cluster list is empty, supply default known servers
287:   if (serverNames.length === 0) {
288:     serverNames.push('secret', 'Nebula', 'Lisbon', 'Solara', 'Athens');
289:   }
290: 
291:   // Build candidate order: preferred server first if specified
292:   const candidates = [];
293:   if (server && server !== 'auto' && serverNames.includes(server)) {
294:     candidates.push(server);
295:   }
296:   for (const s of serverNames) {
297:     if (!candidates.includes(s)) {
298:       candidates.push(s);
299:     }
300:   }
301: 
302:   const errors = [];
303:   for (const candidate of candidates) {
304:     try {
305:       const result = await resolveSingleServer({
306:         server: candidate,
307:         type,
308:         tmdbId,
309:         season,
310:         episode,
311:         wasmModule
312:       });
313: 
314:       return {
315:         success: true,
316:         playlist: result.playlist,
317:         originalUrl: result.playlist,
318:         streamUrl: result.playlist,
319:         server: result.server,
320:         format: 'hls',
321:         captions: result.captions,
322:         rawStream: result.rawStream
323:       };
324:     } catch (err) {
325:       errors.push(err.message);
326:       if (!fallback) {
327:         throw new Error(`Failed to resolve on ${candidate}: ${err.message}`);
328:       }
329:     }
330:   }
331: 
332:   throw new Error(`All servers failed to resolve stream for ${type} ${tmdbId}:\n  ${errors.join('\n  ')}`);
333: }
334: 
335: /**
336:  * Queries external subtitles from subs.wing.st.
337:  * 
338:  * @param {object} options
339:  * @param {string|number} options.tmdbId
340:  * @param {string} [options.type='movie']
341:  * @param {string|number} [options.season]
342:  * @param {string|number} [options.episode]
343:  * @returns {Promise<Array<{ id: string, language: string, url: string }>>}
344:  */
345: async function fetchSubtitles({ tmdbId, type = 'movie', season, episode }) {
346:   const subsType = (type === 'tv' || type === 'series') ? 'tv' : 'movie';
347:   let url = `${SUBS_URL}?type=${subsType}&tmdb=${tmdbId}`;
348:   if (subsType === 'tv') {
349:     url += `&season=${season || 1}&episode=${episode || 1}`;
350:   }
351: 
352:   try {
353:     const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
354:     if (!res.ok) return [];
355:     const data = await res.json();
356:     return data.subtitles || [];
357:   } catch {
358:     return [];
359:   }
360: }
361: 
