43:  * @param {string} baseUrl - The base URL (post-redirect) of the manifest.
44:  * @returns {string} The fully-qualified absolute URL.
45:  */
46: function resolveUrl(rawUri, baseUrl) {
47:   try {
48:     return new URL(rawUri, baseUrl).href;
49:   } catch (err) {
50:     return rawUri;
51:   }
52: }
