54: /**
55:  * Unwraps an existing proxy URL to ensure rewriting is idempotent.
56:  * 
57:  * @param {string} urlStr - The candidate URL string.
58:  * @returns {string} The original unwrapped target URL.
59:  */
60: function unwrapProxyUrl(urlStr) {
61:   try {
62:     const parsed = new URL(urlStr);
63:     if (parsed.pathname === '/hls/proxy' && parsed.searchParams.has('url')) {
64:       return parsed.searchParams.get('url');
65:     }
66:   } catch (_) {
67:     // Ignore URL parse errors
68:   }
69:   return urlStr;
70: }
