74:  * 
75:  * @param {string} urlStr - Target URL.
76:  * @param {string} [contentType] - Content-Type header from upstream response.
77:  * @returns {boolean} True if the resource is an M3U8 playlist.
78:  */
79: function isPlaylistResource(urlStr, contentType = '') {
80:   try {
81:     const pathname = new URL(urlStr).pathname.toLowerCase();
82:     if (pathname.endsWith('.m3u8')) return true;
83:     if (contentType && (contentType.includes('application/vnd.apple.mpegurl') || contentType.includes('application/x-mpegurl'))) {
84:       return true;
85:     }
86:     // Handle edge cases where variant playlists have extensions like .jpg on secondary servers
87:     if (pathname.endsWith('/master') || pathname.endsWith('/playlist') || /playlist\.[a-z0-9]+$/i.test(pathname)) {
