  }

  if (!res.ciphertextBody.equals(origCipher)) {
    console.error('FAIL: ciphertextBody was mutated by clobbering WASM memory! (Shared memory leak)');
  } else {
    console.log('PASS: ciphertextBody is an independent copy!');
  }
}
testBufferCopy();
