    }
  });

  console.log('HTTP status:', res.status);
  console.log('Content-Type:', res.headers.get('content-type'));
  const buf = Buffer.from(await res.arrayBuffer());
  console.log('Total bytes:', buf.length);

  // Parse ISO BMFF top-level boxes
  let offset = 0;
  const boxes = [];
  while (offset + 8 <= buf.length) {
    const size = buf.readUInt32BE(offset);
    const type = buf.subarray(offset + 4, offset + 8).toString('ascii');
    boxes.push({ type, size, offset });
    if (size === 0) {
      // Extends to end of file
      break;
    }
    if (size === 1) {
      // 64-bit size
      const largeSize = Number(buf.readBigUInt64BE(offset + 8));
      offset += largeSize;
    } else {
      offset += size;
    }
  }
  console.log('Top-level ISO BMFF boxes:', boxes);

  // Check ftyp box
  const ftyp = boxes.find(b => b.type === 'ftyp');
  if (ftyp) {
    const majorBrand = buf.subarray(ftyp.offset + 8, ftyp.offset + 12).toString('ascii');
    const minorVersion = buf.readUInt32BE(ftyp.offset + 12);
    const compBrands = [];
    for (let i = ftyp.offset + 16; i < ftyp.offset + ftyp.size; i += 4) {
      compBrands.push(buf.subarray(i, i + 4).toString('ascii'));
    }
    console.log('ftyp:', { majorBrand, minorVersion, compBrands });
  }

  // Check moov and mvex boxes
  const moov = boxes.find(b => b.type === 'moov');
  if (moov) {
    console.log('moov found! size:', moov.size);
    const moovBuf = buf.subarray(moov.offset + 8, moov.offset + moov.size);
    const hasMvex = moovBuf.indexOf(Buffer.from('mvex')) !== -1;
    const hasTrak = moovBuf.indexOf(Buffer.from('trak')) !== -1;
