/**
 * tests/adversarial-m1.js - Empirical Adversarial Test Harness for Milestone 1
 * 
 * Conducts stress tests, boundary tests, and binary integrity audits on:
 * 1. WebAssembly crush.wasm memory stability across 50 iterations, memory detachment, and isolation.
 * 2. AES-256-GCM authentication tag verification, bit-flip corruption detection, and AAD validation.
 * 3. HLS manifest parser edge cases, CRLF handling, URI attribute rewriting, and idempotency.
 * 4. ISO BMFF / fMP4 init.png and media segment binary structure verification.
 */

const crypto = require('crypto');
const http = require('http');
const path = require('path');
const fs = require('fs');

const resolver = require('../server/resolver');
const hlsProxy = require('../server/hls-proxy');
const index = require('../server/index');

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalAdversarialTests = 0;
let passedAdversarialTests = 0;
let failedAdversarialTests = 0;
const testLogs = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Adversarial assertion failed');
  }
}

async function runAdversarialTest(category, name, testFn) {
  totalAdversarialTests++;
  const testId = totalAdversarialTests;
  const startTime = Date.now();
  process.stdout.write(`  [Test ${testId.toString().padStart(2, '0')}] [${category}] ${name} ... `);
  try {
    await testFn();
    const duration = Date.now() - startTime;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    passedAdversarialTests++;
    testLogs.push({ id: testId, category, name, pass: true, duration });
  } catch (err) {
    const duration = Date.now() - startTime;
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Error: ${err.message}${C.reset}`);
    failedAdversarialTests++;
    testLogs.push({ id: testId, category, name, pass: false, error: err.message, duration });
  }
}

/**
 * Suite 1: WebAssembly Linear Memory, Recycling & Isolation
 */
async function runWasmSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 1: WASM Linear Memory Leaks & Buffer Isolation (resolver.js)${C.reset}`);

  const wasmModule = await resolver.initWasm();

  // Test 1: 50 Iterations on Single Reused Instance
  await runAdversarialTest('WASM', 'Memory stability across 50 iterations on single instance', async () => {
    const instance = await WebAssembly.instantiate(wasmModule);
    const initialPages = instance.exports.memory.buffer.byteLength / 65536;

    for (let i = 0; i < 50; i++) {
      const sealed = resolver.sealRequest(instance, {
        server: 'secret',
        type: 'movie',
        tmdbId: 27205 + i
      });
      assert(sealed.responseKey.length === 32, 'responseKey must be 32 bytes');
      assert(sealed.ephemeralPublic.length === 65, 'ephemeralPublic must be 65 bytes');
      assert(sealed.ciphertextBody.length > 98, 'ciphertextBody must exceed header length');
    }

    const finalPages = instance.exports.memory.buffer.byteLength / 65536;
    // Crush.wasm starts at 17 pages and expands by 1 page on first 4KB alloc, then reuses pool
    assert(finalPages <= initialPages + 1, `WASM memory leaked! Grew from ${initialPages} to ${finalPages} pages`);
  });

  // Test 2: 50 Iterations with Fresh Instance per Call (Production resolver flow)
  await runAdversarialTest('WASM', 'Heap bounded across 50 fresh instance instantiations', async () => {
    const memBefore = process.memoryUsage();
    for (let i = 0; i < 50; i++) {
      const inst = await WebAssembly.instantiate(wasmModule);
      const sealed = resolver.sealRequest(inst, {
        server: 'secret',
        type: 'tv',
        tmdbId: 1396,
        season: 1,
        episode: (i % 20) + 1
      });
      assert(sealed.responseKey.length === 32);
    }
    const memAfter = process.memoryUsage();
    const heapGrowthMb = (memAfter.heapUsed - memBefore.heapUsed) / (1024 * 1024);
    assert(heapGrowthMb < 25, `V8 heap growth excessive: ${heapGrowthMb.toFixed(2)} MB`);
  });

  // Test 3: Buffer Copy Isolation from Linear Memory
  await runAdversarialTest('WASM', 'Memory buffer copy isolation (defense against linear clobbering)', async () => {
    const instance = await WebAssembly.instantiate(wasmModule);
    const sealed = resolver.sealRequest(instance, {
      server: 'secret',
      type: 'movie',
      tmdbId: 27205
    });

    const origKey = Buffer.from(sealed.responseKey);
    const origPub = Buffer.from(sealed.ephemeralPublic);
    const origCipher = Buffer.from(sealed.ciphertextBody);

    // Overwrite the entire WASM linear memory with garbage 0xEE
    const mem = new Uint8Array(instance.exports.memory.buffer);
    mem.fill(0xEE);

    assert(sealed.responseKey.equals(origKey), 'responseKey was corrupted by WASM memory mutation (not copied!)');
    assert(sealed.ephemeralPublic.equals(origPub), 'ephemeralPublic was corrupted by WASM memory mutation (not copied!)');
    assert(sealed.ciphertextBody.equals(origCipher), 'ciphertextBody was corrupted by WASM memory mutation (not copied!)');
  });

  // Test 4: Boundary Handling of Oversized Payload
  await runAdversarialTest('WASM', 'Graceful rejection and memory recovery on oversized payload', async () => {
    const instance = await WebAssembly.instantiate(wasmModule);
    const hugeTmdb = '9'.repeat(15000); // 15KB string payload

    let caught = false;
    try {
      resolver.sealRequest(instance, {
        server: 'secret',
        type: 'movie',
        tmdbId: hugeTmdb
      });
    } catch (err) {
      caught = true;
      assert(err.message.includes('invalid length') || err.message.includes('WASM'), 'Unexpected error message');
    }
    assert(caught, 'Oversized payload should have thrown an error');

    // Verify instance is still functional for a valid payload immediately after error
    const validSealed = resolver.sealRequest(instance, {
      server: 'secret',
      type: 'movie',
      tmdbId: 27205
    });
    assert(validSealed.responseKey.length === 32, 'Failed to recover instance after failed oversized request');
  });

  // Test 5: Cryptographic Randomness & Entropy Uniqueness
  await runAdversarialTest('WASM', 'Cryptographic entropy uniqueness across 50 consecutive seals', async () => {
    const instance = await WebAssembly.instantiate(wasmModule);
    const keysSeen = new Set();
    const pubKeysSeen = new Set();
    const ciphersSeen = new Set();

    for (let i = 0; i < 50; i++) {
      const sealed = resolver.sealRequest(instance, {
        server: 'secret',
        type: 'movie',
        tmdbId: 27205
      });
      keysSeen.add(sealed.responseKey.toString('hex'));
      pubKeysSeen.add(sealed.ephemeralPublic.toString('hex'));
      ciphersSeen.add(sealed.ciphertextBody.toString('hex'));
    }

    assert(keysSeen.size === 50, `Key collision detected! Expected 50 unique keys, got ${keysSeen.size}`);
    assert(pubKeysSeen.size === 50, `Public key collision detected! Expected 50 unique, got ${pubKeysSeen.size}`);
    assert(ciphersSeen.size === 50, `Ciphertext collision detected! Expected 50 unique, got ${ciphersSeen.size}`);
  });
}

/**
 * Suite 2: AES-256-GCM Tag Verification & Attack Scenarios
 */
async function runAesGcmSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 2: AES-256-GCM Cryptographic Tag Verification (resolver.js)${C.reset}`);

  const PROTOCOL_ID = 'lumen-gate-v2';
  const responseKey = crypto.randomBytes(32);
  const keyId = 1;
  const ephemeralPublic = crypto.randomBytes(65);
  const iv = crypto.randomBytes(12);

  const payloadObj = {
    status: 200,
    data: {
      stream: [{ playlist: 'https://lightspeed.st/hls/test-uuid/1/master.m3u8' }]
    }
  };
  const plaintext = Buffer.from(JSON.stringify(payloadObj), 'utf8');

  const aad = Buffer.concat([
    Buffer.from(PROTOCOL_ID, 'utf8'),
    Buffer.from([0, 2, keyId]),
    ephemeralPublic
  ]);

  const cipher = crypto.createCipheriv('aes-256-gcm', responseKey, iv);
  cipher.setAAD(aad);
  const enc = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();

  const validResponseBuffer = Buffer.concat([iv, enc, tag]);

  // Test 6: Happy Path Baseline Decryption
  await runAdversarialTest('AES-GCM', 'Baseline authentic decryption roundtrip', async () => {
    const decrypted = resolver.decryptResponse(validResponseBuffer, responseKey, keyId, ephemeralPublic);
    assert(decrypted.status === 200, 'Expected status 200 in decrypted body');
    assert(decrypted.data.stream[0].playlist.includes('test-uuid'), 'Decrypted playlist mismatch');
  });

  // Test 7: Authentication Tag Bit-Flip Attack (Every Single Byte)
  await runAdversarialTest('AES-GCM', 'Rejection of 16 individual bit-flipped authTag bytes', async () => {
    for (let tagByteIdx = 0; tagByteIdx < 16; tagByteIdx++) {
      const corrupted = Buffer.from(validResponseBuffer);
      const tagOffsetInBuf = corrupted.length - 16 + tagByteIdx;
      corrupted[tagOffsetInBuf] ^= 0x01; // flip lowest bit

      let caught = false;
      try {
        resolver.decryptResponse(corrupted, responseKey, keyId, ephemeralPublic);
      } catch (err) {
        caught = true;
        assert(
          err.message.includes('unable to authenticate data') || err.message.includes('Unsupported state'),
          `Unexpected error for tag byte ${tagByteIdx}: ${err.message}`
        );
      }
      assert(caught, `GCM authentication tag failed to catch corruption at tag byte ${tagByteIdx}!`);
    }
  });

  // Test 8: Ciphertext Tampering Attack
  await runAdversarialTest('AES-GCM', 'Rejection of bit-flipped ciphertext at start, middle, and end', async () => {
    const cipherStart = 12;
    const cipherEnd = validResponseBuffer.length - 16 - 1;
    const cipherMid = Math.floor((cipherStart + cipherEnd) / 2);

    for (const offset of [cipherStart, cipherMid, cipherEnd]) {
      const corrupted = Buffer.from(validResponseBuffer);
      corrupted[offset] ^= 0x40;

      let caught = false;
      try {
        resolver.decryptResponse(corrupted, responseKey, keyId, ephemeralPublic);
      } catch (err) {
        caught = true;
        assert(err.message.includes('unable to authenticate data') || err.message.includes('Unsupported state'));
      }
      assert(caught, `GCM failed to catch ciphertext tampering at offset ${offset}!`);
    }
  });

  // Test 9: IV Tampering Attack
  await runAdversarialTest('AES-GCM', 'Rejection of bit-flipped IV bytes', async () => {
    for (const ivOffset of [0, 6, 11]) {
      const corrupted = Buffer.from(validResponseBuffer);
      corrupted[ivOffset] ^= 0x80;

      let caught = false;
      try {
        resolver.decryptResponse(corrupted, responseKey, keyId, ephemeralPublic);
      } catch (err) {
        caught = true;
        assert(err.message.includes('unable to authenticate data') || err.message.includes('Unsupported state'));
      }
      assert(caught, `GCM failed to catch IV tampering at offset ${ivOffset}!`);
    }
  });

  // Test 10: AAD Modification Attacks (Key ID, Protocol ID, Ephemeral Public Key)
  await runAdversarialTest('AES-GCM', 'Rejection of tampered AAD parameters', async () => {
    // 1. Wrong keyId
    let caughtKeyId = false;
    try {
      resolver.decryptResponse(validResponseBuffer, responseKey, keyId + 1, ephemeralPublic);
    } catch (_) { caughtKeyId = true; }
    assert(caughtKeyId, 'Tampered keyId was not rejected by GCM AAD verification');

    // 2. Tampered ephemeral public key
    const corruptedPub = Buffer.from(ephemeralPublic);
    corruptedPub[32] ^= 0x01;
    let caughtPub = false;
    try {
      resolver.decryptResponse(validResponseBuffer, responseKey, keyId, corruptedPub);
    } catch (_) { caughtPub = true; }
    assert(caughtPub, 'Tampered ephemeral public key was not rejected by GCM AAD verification');

    // 3. Wrong AES key
    const wrongKey = crypto.randomBytes(32);
    let caughtKey = false;
    try {
      resolver.decryptResponse(validResponseBuffer, wrongKey, keyId, ephemeralPublic);
    } catch (_) { caughtKey = true; }
    assert(caughtKey, 'Decryption with wrong AES key was not rejected');
  });

  // Test 11: Buffer Truncation & Underflow
  await runAdversarialTest('AES-GCM', 'Rejection of truncated buffers (< 28 bytes boundary)', async () => {
    for (const len of [0, 1, 11, 12, 27]) {
      const truncated = Buffer.alloc(len);
      let caught = false;
      try {
        resolver.decryptResponse(truncated, responseKey, keyId, ephemeralPublic);
      } catch (err) {
        caught = true;
        assert(err.message.includes('too short') || err.message.includes('minimum 28 required'));
      }
      assert(caught, `Buffer of length ${len} was not rejected as too short`);
    }
  });

  // Test 12: Non-JSON Plaintext Decryption Attack
  await runAdversarialTest('AES-GCM', 'Rejection of valid AES-GCM decryption containing malformed JSON', async () => {
    const rawJunk = Buffer.from('NOT_A_JSON_OBJECT_{[[[', 'utf8');
    const c2 = crypto.createCipheriv('aes-256-gcm', responseKey, iv);
    c2.setAAD(aad);
    const encJunk = Buffer.concat([c2.update(rawJunk), c2.final()]);
    const tagJunk = c2.getAuthTag();
    const junkResp = Buffer.concat([iv, encJunk, tagJunk]);

    let caught = false;
    try {
      resolver.decryptResponse(junkResp, responseKey, keyId, ephemeralPublic);
    } catch (err) {
      caught = true;
      assert(err instanceof SyntaxError, `Expected SyntaxError, got ${err.name}: ${err.message}`);
    }
    assert(caught, 'Malformed JSON plaintext did not raise SyntaxError');
  });
}

/**
 * Suite 3: HLS Manifest Parser Edge Cases & Rewriting Idempotency
 */
async function runManifestSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: HLS Manifest Parser Edge Cases & Idempotency (hls-proxy.js)${C.reset}`);

  const baseUrl = 'https://lightspeed.st/hls/test-uuid/1/master.m3u8';
  const variantBaseUrl = 'https://lightspeed.st/hls/test-uuid/1/1080p/playlist.m3u8';
  const proxyPrefix = 'http://127.0.0.1:8088/hls/proxy?url=';

  // Test 13: Master Playlist with Multiple Media and Stream Tags
  await runAdversarialTest('Manifest', 'Master playlist with audio, subs, and video streams rewriting', async () => {
    const master = [
      '#EXTM3U',
      '#EXT-X-VERSION:7',
      '#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="audio-en",NAME="English 5.1",DEFAULT=YES,URI="audio-en/playlist.m3u8"',
      '#EXT-X-MEDIA:TYPE=SUBTITLES,GROUP-ID="subs",NAME="Spanish",URI="subs/es.m3u8"',
      '#EXT-X-STREAM-INF:BANDWIDTH=8000000,RESOLUTION=1920x1080,AUDIO="audio-en",SUBTITLES="subs"',
      '1080p/playlist.m3u8',
      '#EXT-X-STREAM-INF:BANDWIDTH=3500000,RESOLUTION=1280x720,AUDIO="audio-en"',
      '../720p/playlist.m3u8',
      '#EXT-X-STREAM-INF:BANDWIDTH=1500000,RESOLUTION=640x360',
      'https://cdn2.lightspeed.st/hls/360p/playlist.m3u8'
    ].join('\n');

    const rewritten = hlsProxy.rewriteManifest(master, baseUrl, proxyPrefix);

    assert(rewritten.includes('#EXT-X-MEDIA:TYPE=AUDIO'), 'Audio tag lost');
    assert(
      rewritten.includes(`URI="${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/audio-en/playlist.m3u8')}"`),
      'Audio playlist URI not properly rewritten'
    );
    assert(
      rewritten.includes(`URI="${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/subs/es.m3u8')}"`),
      'Subtitles playlist URI not properly rewritten'
    );
    assert(
      rewritten.includes(`${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/1080p/playlist.m3u8')}`),
      '1080p variant stream line not properly rewritten'
    );
    assert(
      rewritten.includes(`${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/720p/playlist.m3u8')}`),
      'Parent relative ../720p variant not normalized properly'
    );
    assert(
      rewritten.includes(`${proxyPrefix}${encodeURIComponent('https://cdn2.lightspeed.st/hls/360p/playlist.m3u8')}`),
      'Absolute external URI not proxied properly'
    );
  });

  // Test 14: fMP4 Fragmented Manifest with init.png & ByteRange
  await runAdversarialTest('Manifest', 'fMP4 variant playlist with init.png and segment chunks', async () => {
    const variant = [
      '#EXTM3U',
      '#EXT-X-VERSION:7',
      '#EXT-X-TARGETDURATION:6',
      '#EXT-X-MAP:URI="init.png",BYTERANGE="943@0"',
      '#EXTINF:6.00000,',
      'seg-v0.png',
      '#EXTINF:6.00000,',
      'seg-v1.png?token=exp123&sign=abc',
      '#EXT-X-ENDLIST'
    ].join('\n');

    const rewritten = hlsProxy.rewriteManifest(variant, variantBaseUrl, proxyPrefix);

    assert(
      rewritten.includes(`URI="${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/1080p/init.png')}",BYTERANGE="943@0"`),
      'init.png URI not rewritten or BYTERANGE corrupted'
    );
    assert(
      rewritten.includes(`${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/1080p/seg-v0.png')}`),
      'seg-v0.png not rewritten'
    );
    assert(
      rewritten.includes(`${proxyPrefix}${encodeURIComponent('https://lightspeed.st/hls/test-uuid/1/1080p/seg-v1.png?token=exp123&sign=abc')}`),
      'Query string in segment URI not preserved'
    );
    assert(rewritten.includes('#EXT-X-ENDLIST'), '#EXT-X-ENDLIST tag lost');
  });

  // Test 15: Idempotency Verification (Prevent Double-Wrapping)
  await runAdversarialTest('Manifest', 'Idempotency: Re-rewriting already-proxied manifest prevents double-proxying', async () => {
    const variant = [
      '#EXTM3U',
      '#EXT-X-MAP:URI="init.png"',
      'seg-0.png'
    ].join('\n');

    const pass1 = hlsProxy.rewriteManifest(variant, variantBaseUrl, proxyPrefix);
    const pass2 = hlsProxy.rewriteManifest(pass1, variantBaseUrl, proxyPrefix);

    // Verify pass2 does NOT contain double url parameter: url=http...url=
    const occurrences = (pass2.match(/hls\/proxy\?url=/g) || []).length;
    assert(occurrences === 2, `Expected exactly 2 proxy prefixes after second pass, found ${occurrences}`);
    assert(!pass2.includes('url=http%3A%2F%2F127.0.0.1%3A8088%2Fhls%2Fproxy'), 'Double wrapping detected!');
  });

  // Test 16: CRLF Windows Line Endings and Empty Lines
  await runAdversarialTest('Manifest', 'CRLF line endings and empty/comment lines handling', async () => {
    const crlfManifest = '#EXTM3U\r\n\r\n# Comment\r\n#EXT-X-MAP:URI="init.png"\r\n\r\n#EXTINF:6.0,\r\nseg-0.png\r\n';
    const rewritten = hlsProxy.rewriteManifest(crlfManifest, variantBaseUrl, proxyPrefix);

    assert(rewritten.includes('# Comment'), 'Comment was stripped');
    assert(rewritten.includes('#EXTINF:6.0,'), '#EXTINF line was modified');
    assert(!rewritten.includes('\r'), 'CR characters leaked into rewritten URL or lines');
  });

  // Test 17: SSRF Protection & URL Validation
  await runAdversarialTest('Manifest', 'validateTargetUrl security and SSRF protection', async () => {
    const validHttp = hlsProxy.validateTargetUrl('https://lightspeed.st/hls/test.m3u8');
    assert(validHttp.valid === true, 'Valid HTTPS url rejected');

    const invalidProto = hlsProxy.validateTargetUrl('file:///etc/passwd');
    assert(invalidProto.valid === false, 'file:// protocol was allowed');

    const ftpProto = hlsProxy.validateTargetUrl('ftp://example.com/media.mp4');
    assert(ftpProto.valid === false, 'ftp:// protocol was allowed');

    const javascriptProto = hlsProxy.validateTargetUrl('javascript:alert(1)');
    assert(javascriptProto.valid === false, 'javascript: URI was allowed');

    const empty = hlsProxy.validateTargetUrl('');
    assert(empty.valid === false, 'Empty URL string was allowed');

    const malformed = hlsProxy.validateTargetUrl('ht tp://invalid-domain');
    assert(malformed.valid === false, 'Malformed URL was allowed');
  });
}

/**
 * Suite 4: ISO BMFF / fMP4 init.png & Segment Binary Verification
 */
async function runFmp4Suite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: ISO BMFF / fMP4 init.png & Binary Segment Integrity${C.reset}`);

  const liveInitUrl = 'https://lightspeed.st/hls/8e7e7dad-ed31-47d4-8243-925232bdeae3/1/1080p/init.png';
  const liveSegUrl = 'https://lightspeed.st/hls/8e7e7dad-ed31-47d4-8243-925232bdeae3/1/1080p/seg-v0.png';

  // Test 18: Live init.png ISO BMFF Structural Verification
  await runAdversarialTest('fMP4', 'init.png binary box structure (ftyp, moov, mvex)', async () => {
    const res = await fetch(liveInitUrl, {
      headers: {
        'Origin': 'https://cinejoy.pk',
        'Referer': 'https://cinejoy.pk/'
      }
    });
    assert(res.status === 200, `Upstream returned status ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    assert(buf.length === 943, `Expected init.png to be exactly 943 bytes, got ${buf.length}`);

    // Parse Box 1: ftyp
    const ftypSize = buf.readUInt32BE(0);
    const ftypType = buf.subarray(4, 8).toString('ascii');
    assert(ftypType === 'ftyp', `Expected box 1 to be 'ftyp', got '${ftypType}'`);
    assert(ftypSize === 28, `Expected ftyp size 28, got ${ftypSize}`);

    const majorBrand = buf.subarray(8, 12).toString('ascii');
    assert(majorBrand === 'iso5', `Expected major brand 'iso5', got '${majorBrand}'`);

    const compBrands = [
      buf.subarray(16, 20).toString('ascii'),
      buf.subarray(20, 24).toString('ascii'),
      buf.subarray(24, 28).toString('ascii')
    ];
    assert(compBrands.includes('iso5') && compBrands.includes('iso6'), 'Missing ISO BMFF compatible brands');

    // Parse Box 2: moov
    const moovOffset = ftypSize;
    const moovSize = buf.readUInt32BE(moovOffset);
    const moovType = buf.subarray(moovOffset + 4, moovOffset + 8).toString('ascii');
    assert(moovType === 'moov', `Expected box 2 to be 'moov', got '${moovType}'`);
    assert(moovSize === 915, `Expected moov size 915, got ${moovSize}`);
    assert(ftypSize + moovSize === buf.length, 'Top-level box sizes do not equal total file size');

    // Parse moov internal boxes: must contain mvex (essential for MSE fragmented MP4 playback!)
    const moovPayload = buf.subarray(moovOffset + 8, moovOffset + moovSize);
    assert(moovPayload.indexOf(Buffer.from('mvex')) !== -1, 'CRITICAL: moov missing mvex box! MSE playback will fail');
    assert(moovPayload.indexOf(Buffer.from('trak')) !== -1, 'moov missing trak box');
    assert(moovPayload.indexOf(Buffer.from('mvhd')) !== -1, 'moov missing mvhd box');
  });

  // Test 19: Live Media Chunk (seg-v0.png) ISO BMFF Verification
  await runAdversarialTest('fMP4', 'seg-v0.png chunk box structure (styp, sidx) & Range handling', async () => {
    const res = await fetch(liveSegUrl, {
      headers: {
        'Origin': 'https://cinejoy.pk',
        'Referer': 'https://cinejoy.pk/',
        'Range': 'bytes=0-1023'
      }
    });
    assert(res.status === 206, `Expected HTTP 206 Partial Content, got ${res.status}`);
    const contentRange = res.headers.get('content-range');
    assert(contentRange && contentRange.startsWith('bytes 0-1023/'), `Invalid Content-Range: ${contentRange}`);

    const buf = Buffer.from(await res.arrayBuffer());
    assert(buf.length === 1024, `Expected 1024 bytes for range 0-1023, got ${buf.length}`);

    // Parse Box 1: styp (Segment Type Box)
    const stypSize = buf.readUInt32BE(0);
    const stypType = buf.subarray(4, 8).toString('ascii');
    assert(stypType === 'styp', `Expected box 1 in chunk to be 'styp', got '${stypType}'`);
    assert(stypSize === 24, `Expected styp size 24, got ${stypSize}`);

    // Parse Box 2: sidx (Segment Index Box)
    const sidxSize = buf.readUInt32BE(stypSize);
    const sidxType = buf.subarray(stypSize + 4, stypSize + 8).toString('ascii');
    assert(sidxType === 'sidx', `Expected box 2 in chunk to be 'sidx', got '${sidxType}'`);
    assert(sidxSize === 52, `Expected sidx size 52, got ${sidxSize}`);
  });

  // Test 20: Origin Enforcement Boundary Check
  await runAdversarialTest('fMP4', 'Origin header enforcement check (404 without Origin vs 200 with Origin)', async () => {
    // Request without Origin header must be rejected by CDN
    const unauthedRes = await fetch(liveInitUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0'
      }
    });
    assert(
      unauthedRes.status === 404,
      `Expected CDN to return 404 for unauthenticated origin, got HTTP ${unauthedRes.status}`
    );

    // Request with Origin: https://cinejoy.pk must succeed
    const authedRes = await fetch(liveInitUrl, {
      headers: {
        'Origin': 'https://cinejoy.pk',
        'Referer': 'https://cinejoy.pk/'
      }
    });
    assert(
      authedRes.status === 200,
      `Expected CDN to return 200 for authenticated Origin, got HTTP ${authedRes.status}`
    );
  });
}

